import"./chunk-VC46IEJQ.js";var e=(a,o)=>({en:a,zh:o}),t=(a,o,h,n,s,i,l,d,r)=>({name:a,desc:o,tour:h,...r?{spoiler:r}:{},source:{confidence:n,refs:s,book:i,unknown:l,interpretation:d}}),w={id:"riverrun",intro:e("The seat of House Tully stands where the Tumblestone flows into the Red Fork: river on two sides, a man-made ditch on the third. Its walls rise sheer from the water, and opening the sluices turns the whole castle into an island.","\u5F92\u5229\u5BB6\u65CF\u7684\u5C45\u57CE\u5750\u843D\u5728\u817E\u77F3\u6CB3\u6C47\u5165\u7EA2\u53C9\u6CB3\u4E4B\u5904\uFF1A\u4E24\u9762\u4E34\u6CB3\uFF0C\u7B2C\u4E09\u9762\u662F\u4EBA\u5DE5\u5F00\u6316\u7684\u58D5\u6C9F\u3002\u57CE\u5899\u81EA\u6C34\u4E2D\u9661\u7136\u62D4\u8D77\uFF0C\u53EA\u8981\u5F00\u95F8\u653E\u6C34\uFF0C\u6574\u5EA7\u57CE\u5821\u4FBF\u6210\u4E86\u4E00\u5EA7\u5B64\u5C9B\u3002"),notes:e("From the novels and reference summaries: the confluence site, the Tumblestone to the north and the Red Fork to the south, a floodable ditch on the west, walls rising from the water, the Water Gate, the Wheel Tower, a great hall, a sept and a godswood. Invented here: the plan, building shapes, every dimension, and the farms and boats around it. The ditch is shown flooded.","\u51FA\u81EA\u5C0F\u8BF4\u4E0E\u53C2\u8003\u8D44\u6599\u6458\u8981\uFF1A\u4E24\u6CB3\u4EA4\u6C47\u7684\u4F4D\u7F6E\uFF0C\u5317\u4E34\u817E\u77F3\u6CB3\u3001\u5357\u4E34\u7EA2\u53C9\u6CB3\uFF0C\u897F\u4FA7\u662F\u53EF\u704C\u6C34\u7684\u58D5\u6C9F\uFF1B\u57CE\u5899\u81EA\u6C34\u4E2D\u62D4\u8D77\uFF1B\u6C34\u95E8\u3001\u6C34\u8F66\u5854\u3001\u5927\u5385\u3001\u5723\u5802\u4E0E\u795E\u6728\u6797\u3002\u672C\u573A\u666F\u81EA\u884C\u8BBE\u8BA1\uFF1A\u5E73\u9762\u5E03\u5C40\u3001\u5EFA\u7B51\u9020\u578B\u3001\u4E00\u5207\u5C3A\u5BF8\uFF0C\u4EE5\u53CA\u5468\u8FB9\u7684\u519C\u820D\u4E0E\u8239\u53EA\u3002\u58D5\u6C9F\u753B\u6210\u5DF2\u704C\u6EE1\u6C34\u7684\u72B6\u6001\u3002"),tour:["confluence-point","water-gate","wheel-tower","triangular-keep","great-hall","sept","godswood","west-gate","western-ditch"],sources:[{ref:"agot",checked:"memory",note:e(`Catelyn's return to Riverrun by boat, the castle's look, the Tully sigil (a leaping silver trout on blue and red) and the words "Family, Duty, Honor"; recalled.`,"\u51EF\u7279\u7433\u4E58\u8239\u8FD4\u56DE\u5954\u6D41\u57CE\u3001\u57CE\u5821\u5916\u89C2\u3001\u5F92\u5229\u5BB6\u65CF\u7EB9\u7AE0\uFF08\u84DD\u7EA2\u5E95\u4E0A\u4E00\u6761\u8DC3\u8D77\u7684\u94F6\u9CDF\uFF09\u4E0E\u65CF\u8BED\u201C\u5BB6\u65CF\u3001\u8D23\u4EFB\u3001\u8363\u8A89\u201D\uFF1B\u51ED\u8BB0\u5FC6\u3002")},{ref:"asos",checked:"memory",note:e("A funeral boat leaves through the Water Gate; recalled in outline.","\u4E00\u8258\u9001\u846C\u8239\u4ECE\u6C34\u95E8\u9A76\u51FA\uFF1B\u4EC5\u51ED\u8BB0\u5FC6\u8BB0\u5F97\u6897\u6982\u3002")},{ref:"affc",checked:"memory",note:e("The siege of Riverrun; recalled in outline only.","\u5954\u6D41\u57CE\u4E4B\u56F4\uFF1B\u4EC5\u51ED\u8BB0\u5FC6\u8BB0\u5F97\u6897\u6982\u3002")},{ref:"awoiaf",checked:"search-snippet",note:e("Search summaries of the wiki and concordance confirm the layout (Tumblestone north, Red Fork south, ditch west, sluices that make an island), the Water Gate on the Tumblestone with a winch-raised portcullis, and the Wheel Tower whose wheel the Tumblestone turns. Pages not fetched.","\u7EF4\u57FA\u4E0E\u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\u5370\u8BC1\u4E86\u57CE\u5821\u683C\u5C40\uFF08\u817E\u77F3\u6CB3\u5728\u5317\u3001\u7EA2\u53C9\u6CB3\u5728\u5357\u3001\u897F\u6709\u58D5\u6C9F\uFF0C\u5F00\u95F8\u5373\u6210\u5B64\u5C9B\uFF09\u3001\u5F00\u5728\u817E\u77F3\u6CB3\u4E0A\u5E76\u4EE5\u7EDE\u76D8\u5347\u964D\u94C1\u95F8\u7684\u6C34\u95E8\uFF0C\u4EE5\u53CA\u7531\u817E\u77F3\u6CB3\u63A8\u52A8\u6C34\u8F66\u7684\u6C34\u8F66\u5854\u3002\u9875\u9762\u672A\u6293\u53D6\u3002")}],landmarks:{"confluence-point":t(e("The Confluence","\u4E24\u6CB3\u4EA4\u6C47\u5904"),e("The castle's eastern point, where the Tumblestone joins the Red Fork.","\u57CE\u5821\u4E1C\u7AEF\u7684\u5C16\u89D2\uFF0C\u817E\u77F3\u6CB3\u5728\u6B64\u6C47\u5165\u7EA2\u53C9\u6CB3\u3002"),e("Riverrun is shaped by water: the two rivers meet at its point.","\u5954\u6D41\u57CE\u56E0\u6C34\u6210\u5F62\uFF1A\u4E24\u6761\u6CB3\u5728\u5B83\u7684\u5C16\u89D2\u5904\u4EA4\u6C47\u3002"),"high",["agot","maps","awoiaf"],e("Riverrun stands at the meeting of the Tumblestone and the Red Fork.","\u5954\u6D41\u57CE\u4F4D\u4E8E\u817E\u77F3\u6CB3\u4E0E\u7EA2\u53C9\u6CB3\u7684\u4EA4\u6C47\u5904\u3002"),e("How the walls meet at the point.","\u5C16\u89D2\u5904\u57CE\u5899\u5982\u4F55\u76F8\u63A5\u3002"),e("A single drum tower caps the apex.","\u4EE5\u4E00\u5EA7\u5706\u5854\u6536\u4F4F\u5C16\u89D2\u3002")),"water-gate":t(e("Water Gate","\u6C34\u95E8"),e("A broad arch, half in the water, closed by a portcullis; boats pass through it from the Tumblestone into the castle.","\u534A\u6D78\u6C34\u4E2D\u7684\u5BBD\u9614\u62F1\u95E8\uFF0C\u4EE5\u94C1\u95F8\u5C01\u95ED\uFF1B\u8239\u53EA\u7531\u6B64\u81EA\u817E\u77F3\u6CB3\u9A76\u5165\u57CE\u5185\u3002"),e("Boats glide in from the river under the Water Gate's portcullis.","\u8239\u53EA\u4ECE\u6CB3\u4E0A\u6ED1\u8FC7\u6C34\u95E8\u7684\u94C1\u95F8\uFF0C\u9A76\u5165\u57CE\u4E2D\u3002"),"high",["agot","asos","awoiaf"],e("A water gate on the Tumblestone, reachable only by boat, closed by a winch-raised portcullis.","\u5F00\u5728\u817E\u77F3\u6CB3\u4E00\u4FA7\u7684\u6C34\u95E8\uFF0C\u53EA\u80FD\u4E58\u8239\u51FA\u5165\uFF0C\u4EE5\u7EDE\u76D8\u5347\u964D\u7684\u94C1\u95F8\u5C01\u95ED\u3002"),e("The exact shape of the arch and what lies inside.","\u62F1\u95E8\u7684\u5177\u4F53\u5F62\u72B6\u53CA\u95E8\u5185\u60C5\u5F62\u3002"),e("Placed on the north (Tumblestone) wall.","\u7F6E\u4E8E\u5317\u4FA7\uFF08\u817E\u77F3\u6CB3\uFF09\u57CE\u5899\u3002"),e("In the fourth book a besieged commander escapes by swimming under the half-raised portcullis.","\u7B2C\u56DB\u5377\u4E2D\uFF0C\u4E00\u4F4D\u88AB\u56F4\u7684\u5B88\u5C06\u8D81\u94C1\u95F8\u534A\u5F00\uFF0C\u4ECE\u95F8\u4E0B\u6F5C\u6E38\u8131\u8EAB\u3002")),"wheel-tower":t(e("Wheel Tower","\u6C34\u8F66\u5854"),e("A tower on the river wall housing a great water wheel turned by the Tumblestone.","\u4E34\u6CB3\u57CE\u5899\u4E0A\u7684\u4E00\u5EA7\u5854\u697C\uFF0C\u5185\u6709\u4E00\u67B6\u7531\u817E\u77F3\u6CB3\u63A8\u52A8\u7684\u5DE8\u5927\u6C34\u8F66\u3002"),e("A great wheel turns in the Tumblestone beneath the tower.","\u5854\u4E0B\uFF0C\u4E00\u67B6\u5DE8\u5927\u7684\u6C34\u8F66\u5728\u817E\u77F3\u6CB3\u4E2D\u7F13\u7F13\u8F6C\u52A8\u3002"),"medium",["agot","awoiaf"],e("A tower housing a large water wheel driven by the Tumblestone; Catelyn passes beneath it on her return.","\u5854\u5185\u88C5\u6709\u4E00\u67B6\u7531\u817E\u77F3\u6CB3\u9A71\u52A8\u7684\u5927\u6C34\u8F66\uFF1B\u51EF\u7279\u7433\u5F52\u6765\u65F6\u66FE\u4ECE\u5854\u4E0B\u7ECF\u8FC7\u3002"),e("What the wheel drives.","\u6C34\u8F66\u5E26\u52A8\u7684\u662F\u4EC0\u4E48\u3002"),e("A single large paddled wheel, animated.","\u4E00\u67B6\u5E26\u6868\u53F6\u7684\u5927\u6C34\u8F66\uFF0C\u6301\u7EED\u8F6C\u52A8\u3002")),"triangular-keep":t(e("The Keep","\u4E3B\u5821"),e("The castle's main keep, here drawn as a triangle to follow the wedge of land.","\u57CE\u5821\u7684\u4E3B\u5821\uFF0C\u6B64\u5904\u987A\u5E94\u6954\u5F62\u5730\u5757\u753B\u6210\u4E09\u89D2\u5F62\u3002"),e("Here the keep follows the land: three sides, three towers.","\u4E3B\u5821\u5728\u6B64\u987A\u7740\u5730\u5F62\u800C\u5EFA\uFF1A\u4E09\u9762\u4E09\u5854\u3002"),"low",["awoiaf"],e("Riverrun has a keep, but no reliable description of its shape was found; the castle as a whole follows the wedge between the rivers.","\u5954\u6D41\u57CE\u6709\u4E3B\u5821\uFF0C\u4F46\u672A\u627E\u5230\u5173\u4E8E\u5176\u5F62\u72B6\u7684\u53EF\u9760\u63CF\u5199\uFF1B\u6574\u5EA7\u57CE\u5821\u5219\u987A\u5E94\u4E24\u6CB3\u4E4B\u95F4\u7684\u6954\u5F62\u5730\u5757\u3002"),e("Its shape, height, interior and relation to the great hall.","\u5F62\u72B6\u3001\u9AD8\u5EA6\u3001\u5185\u90E8\u53CA\u4E0E\u5927\u5385\u7684\u5173\u7CFB\u3002"),e("The triangular plan, three corner turrets and crenellated crown are invented.","\u4E09\u89D2\u5F62\u5E73\u9762\u3001\u4E09\u5EA7\u89D2\u697C\u4E0E\u579B\u53E3\u9876\u5747\u4E3A\u81EA\u884C\u8BBE\u8BA1\u3002")),"great-hall":t(e("Great Hall","\u5927\u5385"),e("The long hall where the Tullys hold court and feast their guests beneath trout banners.","\u5F92\u5229\u5BB6\u65CF\u8BAE\u4E8B\u3001\u5BB4\u5BA2\u7684\u957F\u5385\uFF0C\u5385\u4E2D\u60AC\u6302\u7740\u9CDF\u9C7C\u65D7\u5E1C\u3002"),e("Lords of the riverlands have gathered in this hall in peace and in war.","\u65E0\u8BBA\u5E73\u65F6\u8FD8\u662F\u6218\u65F6\uFF0C\u6CB3\u95F4\u5730\u7684\u9886\u4E3B\u4EEC\u90FD\u66FE\u805A\u96C6\u5728\u8FD9\u5EA7\u5927\u5385\u4E2D\u3002"),"medium",["agot","asos"],e("Riverrun has a great hall with a high table, where lords gather and feasts are held.","\u5954\u6D41\u57CE\u6709\u8BBE\u4E3B\u684C\u7684\u5927\u5385\uFF0C\u9886\u4E3B\u4EEC\u5728\u6B64\u805A\u4F1A\uFF0C\u5BB4\u5E2D\u4E5F\u5728\u6B64\u4E3E\u884C\u3002"),e("Its size and decoration.","\u5C3A\u5BF8\u4E0E\u88C5\u9970\u3002"),e("A tiled, gabled hall in the inner ward, with lit windows at night.","\u5185\u9662\u4E2D\u4E00\u5EA7\u74E6\u9876\u5C71\u5899\u5385\uFF0C\u5165\u591C\u7A97\u5185\u4EAE\u706F\u3002"),e("At the end of the first book the lords gathered here proclaim a new king.","\u7B2C\u4E00\u5377\u672B\uFF0C\u805A\u96C6\u4E8E\u6B64\u7684\u9886\u4E3B\u4EEC\u62E5\u7ACB\u4E86\u4E00\u4F4D\u65B0\u738B\u3002")),sept:t(e("Sept","\u5723\u5802"),e("The castle sept, where the Tullys, who keep the Faith of the Seven, pray and marry.","\u57CE\u4E2D\u5723\u5802\uFF1B\u5949\u884C\u4E03\u795E\u4FE1\u4EF0\u7684\u5F92\u5229\u5BB6\u65CF\u5728\u6B64\u7948\u7977\u3001\u6210\u5A5A\u3002"),e("The Tullys keep the Seven, and marry in their sept.","\u5F92\u5229\u5BB6\u65CF\u4FE1\u5949\u4E03\u795E\uFF0C\u5A5A\u793C\u4E5F\u5728\u5723\u5802\u4E2D\u4E3E\u884C\u3002"),"medium",["agot","asos"],e("Riverrun has a sept; the Tullys follow the Seven, and Catelyn was married there.","\u5954\u6D41\u57CE\u6709\u4E00\u5EA7\u5723\u5802\uFF1B\u5F92\u5229\u5BB6\u65CF\u4FE1\u5949\u4E03\u795E\uFF0C\u51EF\u7279\u7433\u4FBF\u662F\u5728\u6B64\u6210\u5A5A\u3002"),e("Its form and position.","\u5F62\u5236\u4E0E\u4F4D\u7F6E\u3002"),e("A seven-sided plan chosen to echo the Seven.","\u53D6\u4E03\u8FB9\u5F62\u5E73\u9762\uFF0C\u4EE5\u547C\u5E94\u4E03\u795E\u3002")),godswood:t(e("Godswood","\u795E\u6728\u6797"),e("A light, airy wood of tall trees and streams, gentler than the dark godswoods of the North.","\u9AD8\u6811\u6210\u836B\u3001\u6EAA\u6C34\u6F7A\u6F7A\u7684\u660E\u4EAE\u6797\u5730\uFF0C\u8FDC\u6BD4\u5317\u5883\u9634\u90C1\u7684\u795E\u6728\u6797\u6E29\u548C\u3002"),e("Riverrun's godswood is bright and green, nothing like Winterfell's.","\u5954\u6D41\u57CE\u7684\u795E\u6728\u6797\u660E\u4EAE\u9752\u7FE0\uFF0C\u4E0E\u4E34\u51AC\u57CE\u622A\u7136\u4E0D\u540C\u3002"),"medium",["agot"],e("Catelyn remembers Riverrun's godswood as a light, airy place of tall trees and streams.","\u51EF\u7279\u7433\u8BB0\u5FC6\u4E2D\uFF0C\u5954\u6D41\u57CE\u7684\u795E\u6728\u6797\u660E\u4EAE\u901A\u900F\uFF0C\u9AD8\u6811\u6797\u7ACB\uFF0C\u6EAA\u6C34\u4EA4\u9519\u3002"),e("Its size, position and whether it has a heart tree.","\u89C4\u6A21\u3001\u4F4D\u7F6E\uFF0C\u4EE5\u53CA\u662F\u5426\u6709\u5FC3\u6811\u3002"),e("Placed in the south-west of the inner ward; the weirwood is the scene's addition.","\u7F6E\u4E8E\u5185\u9662\u897F\u5357\uFF1B\u5176\u4E2D\u7684\u9C7C\u6881\u6728\u4E3A\u672C\u573A\u666F\u6DFB\u52A0\u3002")),"west-gate":t(e("West Gate","\u897F\u95E8"),e("The landward gate, reached by a drawbridge across the ditch.","\u9646\u8DEF\u57CE\u95E8\uFF0C\u987B\u7ECF\u540A\u6865\u8D8A\u8FC7\u58D5\u6C9F\u65B9\u80FD\u8FDB\u5165\u3002"),e("The only land approach crosses the ditch by drawbridge.","\u552F\u4E00\u7684\u9646\u8DEF\u987B\u7ECF\u540A\u6865\u8D8A\u8FC7\u58D5\u6C9F\u3002"),"medium",["agot","awoiaf"],e("The landward side is closed off by the ditch; the castle has a main gate and drawbridge on that side.","\u9646\u4FA7\u4EE5\u58D5\u6C9F\u5C01\u95ED\uFF0C\u4E3B\u57CE\u95E8\u4E0E\u540A\u6865\u5C31\u8BBE\u5728\u8FD9\u4E00\u9762\u3002"),e("The gate's design.","\u57CE\u95E8\u6837\u5F0F\u3002"),e("A twin-towered gatehouse and a plank drawbridge.","\u53CC\u5854\u95E8\u697C\u4E0E\u6728\u677F\u540A\u6865\u3002")),"western-ditch":t(e("The Ditch","\u897F\u4FA7\u58D5\u6C9F"),e("A man-made ditch on the west side; when the sluices open it fills with river water and the castle becomes an island.","\u897F\u4FA7\u7684\u4EBA\u5DE5\u58D5\u6C9F\uFF1B\u5F00\u95F8\u540E\u6CB3\u6C34\u704C\u5165\uFF0C\u57CE\u5821\u968F\u5373\u56DB\u9762\u73AF\u6C34\u3002"),e("Open the sluices and Riverrun becomes an island.","\u5F00\u95F8\u653E\u6C34\uFF0C\u5954\u6D41\u57CE\u4FBF\u6210\u5B64\u5C9B\u3002"),"high",["agot","awoiaf"],e("A ditch closes the landward side and can be flooded from the rivers through sluice gates.","\u58D5\u6C9F\u5C01\u4F4F\u9646\u4FA7\uFF0C\u53EF\u7ECF\u7531\u6C34\u95F8\u5F15\u6CB3\u6C34\u704C\u6EE1\u3002"),e("Its width and depth, and when it is kept dry.","\u5BBD\u5EA6\u3001\u6DF1\u5EA6\uFF0C\u4EE5\u53CA\u5E73\u65F6\u662F\u5426\u5E72\u6DB8\u3002"),e("Shown flooded for clarity.","\u4E3A\u6E05\u6670\u8D77\u89C1\uFF0C\u753B\u6210\u5DF2\u704C\u6EE1\u6C34\u7684\u72B6\u6001\u3002"))}};export{w as default};
